{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Merck-3, a hydroxyethylamine peptidomimetic with high transfer relevance, was undetectable in mouse brain after i.v. dosing despite ~1.3 µM plasma exposure and was a P-gp substrate, with brain levels rising in mdr1A-deficient mice, demonstrating poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Amprenavir and related HIV protease inhibitors sharing the hydroxyethylamine/carbamate/sulfonamide scaffold do not reach sufficient CSF concentrations, supporting poor CNS penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Sacubitril, a smaller and less polar peptidomimetic prodrug, showed very low CSF and brain penetration in non-human primates (CSF:plasma ≤0.0044, brain:plasma ≤0.0326), indicating that this amide/ester class does not achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Lisdexamfetamine, a hydrophilic amino acid amide, was not detected in rat brain after oral dosing, illustrating that amide-containing, high-polarity molecules can be effectively excluded from the CNS.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted fail: the most transferable direct CNS measurements (Merck-3, amprenavir, sacubitril, LDX) all show poor brain/CSF exposure or P-gp efflux in chemotypes sharing the query's hydroxyethylamine/amide/carbamate and high-polarity features; the query's larger size and higher TPSA/HBD/HBA further argue against meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/CSF measurement for the query molecule itself.",
    "Possible active uptake or prodrug bioactivation was not experimentally assessed.",
    "C18 human CSF detection of LBQ657 is qualitative and does not establish meaningful exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

